#ifndef INTERRUPTS_H_COMPAT_SHIM
#define INTERRUPTS_H_COMPAT_SHIM

/*
 * Manual compatibility shim (do not delete, this file is not generated by MCC).
 *
 * The cross-family USB Full-Speed driver drv_usbfsv1.c unconditionally includes
 * the legacy AVR/SAM-style "interrupts.h". This PIC32CX Cortex-M build instead
 * generates the interrupt system service at system/int/sys_int.h. Route the
 * legacy include to that header so no generated USB source file has to be edited
 * (editing a generated file would be reverted on the next MCC generate).
 */

#include "system/int/sys_int.h"

#endif /* INTERRUPTS_H_COMPAT_SHIM */
